const orTimer=(r,big)=>{const dl=orDl(r);if(!dl)return `<span class="otm mute">${I("timer-off")}<b>${t("لا يوجد موعد نهائي","No deadline")}</b></span>`;const v=orTmVal(dl),ph=orPhase[r.st];return `<span class="otm ${v.st}${big?" big":""}" data-ordl="${dl}" title="${t(`${ph[1]} (${ph[0]} ساعة)`,`${ph[2]} (${ph[0]}h)`)}"><i class="otm-d"></i><b class="num otm-v">${v.txt}</b><small class="otm-l">${v.lbl}</small></span>`};
