 const stt=e.target.closest("[data-orstart]");if(stt){const r=orRows.find(x=>x.id===stt.dataset.orstart);if(r){r.st="started";r.tr="TR-2026-00"+(40+orRows.filter(x=>x.tr).length);if(r.agent==="—")r.agent=t("مشرف النظام","Supervisor")}ORMENU=null;orKill();render();clToast("تم تحديث حالة الطلب إلى «قيد المعالجة»","Processing started");return}
