const SEC=(ic,title,inner,extra)=>`<div class="card sec"><div class="sec-h">${X(ic)}<b>${title}</b>${extra||""}</div>${inner}</div>`;
const KV=fs=>`<div class="kvgrid">${fs.map(f=>`<div class="kv"><span>${f[0]}</span><b>${f[1]}</b></div>`).join("")}</div>`;
const TAG=(cls,txt)=>`<span class="tag ${cls}">${txt}</span>`;
const SW=on=>`<span class="sw ${on?"on":""}"></span>`;
const ROW=(title,sub,ctl)=>`<div class="actrow sm"><div><b>${title}</b>${sub?`<small>${sub}</small>`:""}</div>${ctl}</div>`;
const FLD=(label,ctl,req,hint,full)=>`<div class="fld${full?" full":""}"><label>${label}${req?' <i class="rq">*</i>':""}</label>${ctl}${hint?`<small class="fhint">${hint}</small>`:""}</div>`;
const SEL=opts=>`<select>${opts.map(o=>`<option>${o}</option>`).join("")}</select>`;
