const TXT=(ph,rows)=>`<textarea rows="${rows||3}" placeholder="${ph||""}"></textarea>`;
const STAT=(cls,ic,label,v,on)=>`<div class="scard${on?" on":""}"><span class="sci ${cls}">${X(ic)}</span><span class="sct">${label}</span><b class="num">${v}</b></div>`;
const PAGER=txt=>`<div class="tfoot"><span>${txt}</span><div class="pager"><button>${X("chevron-right")}</button><button class="on">1</button><button>2</button><button>3</button><button>${X("chevron-left")}</button></div></div>`;
const ACTS=a=>`<div class="rowacts">${a.map(x=>`<button class="icon-btn pri" title="${x[1]}" ${x[2]||""}>${X(x[0])}</button>`).join("")}</div>`;
const HEAD=(title,sub,actions,back)=>`<div class="page-head"><div>${back?`<a class="back" href="#" data-go="${back[0]}" style="margin:0 0 8px">${X("arrow-right")}<span>${back[1]}</span></a>`:""}<h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions||""}</div></div>`;
const B=(cls,ic,txt,attr)=>`<button class="btn btn-${cls}" ${attr||""}>${ic?X(ic):""}${txt}</button>`;
const TABS=(list,on)=>`<div class="vtabs">${list.map(x=>`<button class="${x[0]===on?"on":""}" ${x[0].startsWith("#")?"":`data-go="${x[0]}"`}>${X(x[1])}<span>${x[2]}</span>${x[3]!=null?`<em class="num">${x[3]}</em>`:""}</button>`).join("")}</div>`;
const CHIPS=(list)=>`<div class="cx-chips">${list.map((c,i)=>`<button class="${i===0?"on":""}">${c[1]?`<i class="d ${c[1]}"></i>`:""}${c[0]}<b class="num">${c[2]}</b></button>`).join("")}</div>`;
const STEPS=(list)=>`<div class="card"><div class="sec-h">${X("list-ordered")}<b>أقسام الفورم</b></div><div class="steps">${list.map((s,i)=>`<button class="step"><span class="stepn num">${i+1}</span><span>${s}</span></button>`).join("")}</div></div>`;
const FS=(n,title,inner)=>`<div class="card sec"><div class="fs-h"><span class="fs-n num">${n}</span><b>${title}</b></div>${inner}</div>`;

