 const sk={c:r=>r.c,dr:r=>r.dr,cr:r=>r.cr,o:r=>r.o,p:r=>r.p}[RS.sort||"c"]||(r=>r.c);rows.sort((a,b)=>{const x=sk(a),y=sk(b);return (x>y?1:x<y?-1:0)*RS.dir});
