  if((el=g("[data-flt]"))){const k=el.dataset.flt,L=UI.L;L.tasks=L.tasks.includes(k)?L.tasks.filter(x=>x!==k):[...L.tasks,k];paint();return}
  if((el=g("[data-fuacc]"))){UI.U.acc=el.dataset.fuacc;paint();return}
