/* rq interactions: in-page tabs, drawers, bulk selection */
document.addEventListener("click",e=>{
 const t=e.target.closest("[data-rq-tab]");
 if(t){const [g,n]=t.dataset.rqTab.split(":");
  document.querySelectorAll(`.rq-tabs [data-rq-tab^="${g}:"]`).forEach(b=>b.classList.toggle("on",b.dataset.rqTab===g+":"+n));
  document.querySelectorAll(`[data-rq-pane^="${g}:"]`).forEach(p=>{p.hidden=p.dataset.rqPane!==g+":"+n});return}
 if(e.target.closest("[data-rq-x]")||e.target.classList.contains("rq-ov")){const ov=e.target.closest(".rq-ov");if(ov)ov.hidden=true;return}
 const o=e.target.closest("[data-rq-open]");
 if(o){if(e.target.closest("[data-rq-stop]")&&!e.target.closest("button[data-rq-open]"))return;
  const d=document.querySelector(`[data-rq-dr="${o.dataset.rqOpen}"]`);if(d){if(d.parentNode!==document.body){document.querySelectorAll("body>.rq-ov").forEach(x=>x.remove());document.body.appendChild(d)}d.hidden=false;e.preventDefault()}}
});
document.addEventListener("keydown",e=>{if(e.key==="Escape")document.querySelectorAll(".rq-ov:not([hidden])").forEach(o=>o.hidden=true)});
document.addEventListener("change",e=>{
 const a=e.target.closest("[data-rq-all]"),c=e.target.closest("[data-rq-c]");if(!a&&!c)return;
 const g=(a||c).dataset.rqAll||(a||c).dataset.rqC;
 if(a)document.querySelectorAll(`[data-rq-c="${g}"]`).forEach(x=>x.checked=a.checked);
 const n=document.querySelectorAll(`[data-rq-c="${g}"]:checked`).length;document.querySelectorAll(`[data-rq-n="${g}"]`).forEach(x=>x.textContent=n);
});


