const cpTabsH=on=>`<div class="vtabs">${[["coupons","ticket-percent","الكوبونات"],["couponsHourly","clock","كوبونات الساعات"],["couponBulk","layers","بالجملة"],["couponReport","bar-chart-3","التقرير"],["couponSettings","settings-2","الإعدادات"]].map(x=>`<button class="${x[0]===on?"on":""}" data-go="${x[0]}">${X(x[1])}<span>${x[2]}</span></button>`).join("")}</div>`;
S.couponsHourly=()=>`
 ${HEAD("كوبونات حجز الساعات","أكواد خصم حجوزات الساعات من لوحة الحجز والموقع، تُطبَّق على إجمالي الحجز مباشرة.",B("ghost","ticket-percent","كوبونات الاستقدام والتأجير",'data-go="coupons"')+B("primary","plus","كوبون ساعات جديد",'data-rrhc'))}
 ${cpTabsH("couponsHourly")}
 <div class="statgrid">${STAT("g","ticket-percent","كوبونات نشطة","3")+STAT("n","calendar-check","حجوزات بكوبون هذا الشهر","96")+STAT("a","hourglass","قاربت على النفاد","1")+STAT("r","pause","موقوفة","1")}</div>
 <div class="rr-hc"><div>
  <div class="fbar">${SEARCH("الكود…")}${FB("الفئة",["كل الفئات","التنظيف المنزلي","التنظيف العميق"])}${FB("الحالة",["الكل","نشط","قارب على النفاد","منتهي","موقوف"])}</div>
  <div class="card flush"><div class="tw"><table><thead><tr><th>الكود</th><th>القيمة</th><th>حد أدنى</th><th>الفئة</th><th>الصلاحية</th><th>الاستخدام</th><th>الحالة</th><th class="act"></th></tr></thead><tbody>
  ${HC.map(c=>{const s=hcState(c);return `<tr><td><span class="cpcode">${c[0]}</span></td><td>${c[1]==="percent"?`<b class="num">${c[2]}%</b>`:`<b class="num">${c[2]}</b> ر.س`}<small class="empty"> ${c[1]==="percent"?"نسبة":"مبلغ ثابت"}</small></td><td>${c[3]?`<span class="num">${c[3]}</span> ر.س`:MUTED("—")}</td><td>${c[4]||"كل الفئات"}</td><td class="num"><small>${c[5]||"من الآن"} ← ${c[6]||"مفتوح"}</small></td><td>${useBar(c[7],c[8])}</td><td>${TAG(s[0],s[1])}</td><td class="act">${ACTS([["pencil","تعديل",'data-rrhc'],[c[9]?"pause":"play",c[9]?"إيقاف":"تفعيل"]])}</td></tr>`}).join("")}
  </tbody></table></div></div></div>
  ${SEC("plus-circle","كوبون ساعات جديد",`<div class="fgrid">${FLD("الكود",INP("","SUMMER30",1),1,"حروف إنجليزية وأرقام و - و _ فقط")}${FLD("النوع",SEL(["نسبة %","مبلغ ثابت"]))}${FLD("القيمة",INP("","30",1,"number"),1,"النسبة لا تتجاوز 100")}${FLD("حد أدنى للحجز (ر.س)",INP("0","",1,"number"))}${FLD("الفئة",SEL(["كل الفئات","التنظيف المنزلي","التنظيف العميق"]))}${FLD("يبدأ في",'<input type="date">')}${FLD("ينتهي في",'<input type="date">')}${FLD("حد الاستخدام",INP("بدون حد","",1,"number"))}</div>
   <div class="cx-info">${X("info")}<span>يُنشأ الكوبون مفعّلاً. الحالة تتغير من زر التفعيل والإيقاف فقط، فلا يعيد التعديل تفعيل كوبون موقوف.</span></div>
   <div class="cpprev rr-cpprev"><span class="cpcode">SUMMER30</span><div><b>خصم 30% على حجز الساعات</b><small>كل الفئات · بدون حد استخدام</small></div></div>
   <div class="cx-right">${B("ghost","","إلغاء")}${B("primary","save","حفظ الكوبون")}</div>`)}
 </div>`;

