document.addEventListener("click",e=>{
 const t=e.target.closest("[data-o2t]");
 if(t){e.preventDefault();const g=t.dataset.o2t.split(":")[0];
  document.querySelectorAll(`[data-o2t^="${g}:"]`).forEach(b=>b.classList.toggle("on",b.dataset.o2t===t.dataset.o2t&&b.closest(".o2-tabs")!==null));
  document.querySelectorAll(`[data-o2p^="${g}:"]`).forEach(p=>p.hidden=p.dataset.o2p!==t.dataset.o2t);return}
 const s=e.target.closest("[data-o2sel]");
 if(s){s.parentElement.querySelectorAll("[data-o2sel]").forEach(b=>b.classList.toggle("on",b===s));return}
 const pk=e.target.closest("[data-o2pick]");
 if(pk){pk.closest("tr").querySelectorAll("[data-o2pick]").forEach(b=>b.classList.toggle("on",b===pk));return}
 const ac=e.target.closest(".o2-acc");
 if(ac){ac.closest("tr").querySelectorAll(".o2-acc").forEach(b=>{b.classList.toggle("on",b===ac);const tg=b.querySelector(".tag");if(tg){tg.className="tag "+(b===ac?"g":"n");tg.textContent=b===ac?"أساسي":"يُدمج"}});return}
 if(e.target.closest("[data-o2allread]")){document.querySelectorAll(".o2-ni.unread").forEach(n=>{n.classList.remove("unread");const d=n.querySelector(".udot");if(d)d.remove()});return}
 const rd=e.target.closest("[data-o2read]");
 if(rd&&!e.target.closest("[data-go]")){rd.classList.remove("unread");const d=rd.querySelector(".udot");if(d)d.remove()}
 const sg=e.target.closest(".o2-seg button,.o2-chips button");
 if(sg){sg.parentElement.querySelectorAll("button").forEach(b=>b.classList.toggle("on",b===sg))}
});


