const liveCal=()=>{const n=new Date(),y=n.getFullYear(),m=n.getMonth(),dn=new Date(y,m+1,0).getDate(),off=(new Date(y,m,1).getDay()+1)%7;
 const ev=TRV.map(e=>{const [h,mi]=e[1].split(":").map(Number),d=new Date(y,m,n.getDate()+e[0],h,mi);return {d,t:e[1],k:e[2],f:e[3],s:e[4],st:e[5]}});
 const next=ev.filter(e=>e.d>n).slice(0,5),cells=[];for(let i=0;i<off;i++)cells.push(`<div class="cd out"></div>`);
 for(let i=1;i<=dn;i++){const l=ev.filter(e=>e.d.getMonth()===m&&e.d.getFullYear()===y&&e.d.getDate()===i),tod=i===n.getDate();cells.push(`<div class="cd${tod?" tod":""}"><span class="dn num">${i}</span>${l.slice(0,2).map(e=>`<span class="ev ${e.k} ${e.st}" ${TIP(`<b>${e.f} · ${e.t}</b>${e.s}`)}>${e.t} ${e.f}</span>`).join("")}${l.length>2?`<small>+${l.length-2}</small>`:""}</div>`)}
 return `<div class="ld-cal"><div class="cm"><div class="ct"><b>${n.toLocaleDateString("ar-EG-u-nu-latn-ca-gregory",{month:"long",year:"numeric"})}</b><span class="live"><i></i>مباشر · <span class="num" data-ldclock>--:--:--</span></span></div><div class="gr">${["السبت","الأحد","الاثنين","الثلاثاء","الأربعاء","الخميس","الجمعة"].map(d=>`<small class="wd">${d}</small>`).join("")}${cells.join("")}</div><div class="ld-lg"><span><i style="background:#2a78d6"></i>وصول</span><span><i style="background:#6250d6"></i>ترحيل</span><span><i style="background:var(--amber)"></i>بدون تأكيد حجز</span><span><i style="background:#c9d3e2"></i>منتهية</span></div></div>
 <aside class="ag"><h4>الرحلات القادمة</h4>${next.map((e,i)=>`<div class="ai ${e.st}${i?"":" nx"}"><span class="ni ${e.st==="a"?"a":e.k==="arr"?"g":"n"}">${X(e.k==="arr"?"plane-landing":"plane-takeoff")}</span><div><b>${e.f}</b><small>${e.s}</small><small class="num">${e.d.toLocaleDateString("ar-EG-u-nu-latn-ca-gregory",{weekday:"long",day:"numeric",month:"short"})} · ${e.t}</small></div><em class="num" data-ldcd="${e.d.getTime()}">--</em></div>`).join("")}</aside></div>`};
if(!window.__ldTick){window.__ldTick=setInterval(()=>{const n=new Date(),p=x=>String(x).padStart(2,"0");document.querySelectorAll("[data-ldclock]").forEach(e=>e.textContent=p(n.getHours())+":"+p(n.getMinutes())+":"+p(n.getSeconds()));document.querySelectorAll("[data-ldcd]").forEach(e=>{const s=Math.floor((+e.dataset.ldcd-n)/1000);if(s<=0){e.textContent="الآن";return}const d=Math.floor(s/86400),h=Math.floor(s%86400/3600),m=Math.floor(s%3600/60);e.textContent=d?`${d} ي ${h} س`:`${p(h)}:${p(m)}:${p(s%60)}`})},1000)}
const dailyArr=()=>{const w={"-2":1,0:2,1:1,2:1,5:3,8:1},n=new Date(),l=[];for(let i=-3;i<=10;i++){const d=new Date(n.getFullYear(),n.getMonth(),n.getDate()+i);l.push([i?`${d.getDate()}/${d.getMonth()+1}`:"اليوم",w[i]||0,i?"":"t"])}return cols(l,{unit:"عاملة",c:"#2a78d6"})};
